import subprocess, re
from collections import deque

# Read maze
with open('maze.txt') as f:
    grid = [list(line.rstrip('\n')) for line in f]

R = len(grid)
C = len(grid[0])
for r in range(R):
    for c in range(C):
        if grid[r][c] == '@':
            start = (r, c)
        if grid[r][c] == 'E':
            end = (r, c)

# BFS
from collections import deque
q = deque([start])
prev = {start: None}
dirs = {'up': (-1,0), 'down': (1,0), 'left': (0,-1), 'right': (0,1)}
while q:
    r, c = q.popleft()
    if (r, c) == end:
        break
    for d, (dr, dc) in dirs.items():
        nr, nc = r+dr, c+dc
        if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != '#' and (nr,nc) not in prev:
            prev[(nr,nc)] = (r, c, d)
            q.append((nr,nc))

# Reconstruct
path = []
cur = end
while prev[cur] is not None:
    pr, pc, d = prev[cur]
    path.append(d)
    cur = (pr, pc)
path.reverse()
print(' '.join(path))
print(len(path))
EOF
