with open('maze.txt') as f:
    lines = [line.rstrip('\n') for line in f]
grid = [list(l) for l in lines]
R = len(grid)
C = len(grid[0])

from collections import deque

def flood(start):
    q = deque([start])
    prev = {start: None}
    dirs = {'up': (-1,0), 'down': (1,0), 'left': (0,-1), 'right': (0,1)}
    while q:
        r, c = q.popleft()
        for d, (dr, dc) in dirs.items():
            nr, nc = r+dr, c+dc
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != '#' and (nr,nc) not in prev:
                prev[(nr,nc)] = (r, c, d)
                q.append((nr,nc))
    return prev

s = flood((1,1))
e = flood((25,25))

for r in range(R):
    row = ''
    for c in range(C):
        if (r,c) in s:
            row += 'o'
        elif (r,c) in e:
            row += 'x'
        else:
            row += grid[r][c]
    print(row)
