grid = [list(r) for r in maze if r]
R = len(grid); C = len(grid[0])
from collections import deque
# find @
start=None; end=None
for r in range(R):
    for c in range(C):
        if grid[r][c]=='@': start=(r,c)
        if grid[r][c]=='E': end=(r,c)
# flood from start
q=deque([start]); sseen={start}
while q:
    r,c=q.popleft()
    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr,nc=r+dr,c+dc
        if 0<=nr<R and 0<=nc<C and grid[nr][nc] in '.E@' and (nr,nc) not in sseen:
            sseen.add((nr,nc)); q.append((nr,nc))
# flood from end
q=deque([end]); eseen={end}
while q:
    r,c=q.popleft()
    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr,nc=r+dr,c+dc
        if 0<=nr<R and 0<=nc<C and grid[nr][nc] in '.E@' and (nr,nc) not in eseen:
            eseen.add((nr,nc)); q.append((nr,nc))
# visualize
for r in range(R):
    row=''
    for c in range(C):
        if (r,c)==start: row+='@'
        elif (r,c)==end: row+='E'
        elif (r,c) in sseen: row+='S'
        elif (r,c) in eseen: row+='e'
        else: row+='#'
    print(row)
print('start size',len(sseen),'end size',len(eseen))
"
