{"command": "python3 << 'EOF'
from collections import deque

with open('maze.txt') as f:
    lines = [line.rstrip('\n') for line in f]

grid = lines
R = len(grid)
C = max(len(r) for r in grid)

start = None
end = None
for i in range(R):
    for j in range(len(grid[i])):
        if grid[i][j] == '@':
            start = (i,j)
        elif grid[i][j] == 'E':
            end = (i,j)

print("start", start, "end", end)

# BFS
q = deque([start])
prev = {start: None}
visited = set([start])
dirs = {'up':(-1,0),'down':(1,0),'left':(0,-1),'right':(0,1)}
while q:
    cur = q.popleft()
    if cur == end:
        break
    for d,(di,dj) in dirs.items():
        ni,nj = cur[0]+di, cur[1]+dj
        if 0<=ni<R and 0<=nj<len(grid[ni]) and grid[ni][nj] in '.E@' and (ni,nj) not in visited:
            visited.add((ni,nj))
            prev[(ni,nj)] = (cur, d)
            q.append((ni,nj))

# reconstruct
path = []
cur = end
while prev[cur] is not None:
    p, d = prev[cur]
    path.append(d)
    cur = p
path.reverse()
print(len(path))
print(' '.join(path))
EOF"}

{"command": "python3 << 'EOF'
from collections import deque

with open('maze.txt') as f:
    lines = [line.rstrip('\n') for line in f]

grid = lines
R = len(grid)
C = max(len(r) for r in grid)

start = None
end = None
for i in range(R):
    for j in range(len(grid[i])):
        if grid[i][j] == '@':
            start = (i,j)
        elif grid[i][j] == 'E':
            end = (i,j)

print("start", start, "end", end)

# BFS - treat # as wall
q = deque([start])
prev = {start: None}
visited = set([start])
dirs = {'up':(-1,0),'down':(1,0),'left':(0,-1),'right':(0,1)}
while q:
    cur = q.popleft()
    if cur == end:
        break
    for d,(di,dj) in dirs.items():
        ni,nj = cur[0]+di, cur[1]+dj
        if 0<=ni<R and 0<=nj<len(grid[ni]):
            c = grid[ni][nj]
            if c != '#' and (ni,nj) not in visited:
                visited.add((ni,nj))
                prev[(ni,nj)] = (cur, d)
                q.append((ni,nj))

print("end in visited:", end in visited)
print("visited count:", len(visited))

if end in prev:
    path = []
    cur = end
    while prev[cur] is not None:
        p, d = prev[cur]
        path.append(d)
        cur = p
    path.reverse()
    print(len(path))
    print(' '.join(path))
else:
    # print reachable cells
    for i in range(R):
        row=''
        for j in range(len(grid[i])):
            if (i,j) in visited:
                row+='o'
            else:
                row+=grid[i][j]
        print(row)
EOF"}

