from collections import deque

with open('maze.txt') as f:
    lines = [l.rstrip('\n') for l in f]

grid = lines
R = len(grid)

end = (27,27)

# flood from end
q = deque([end])
visited = set([end])
while q:
    cur = q.popleft()
    for di,dj in [(-1,0),(1,0),(0,-1),(0,1)]:
        ni,nj = cur[0]+di, cur[1]+dj
        if 0<=ni<R and 0<=nj<len(grid[ni]) and grid[ni][nj] != '#' and (ni,nj) not in visited:
            visited.add((ni,nj))
            q.append((ni,nj))

print("end component size:", len(visited))
# print the component
for i in range(R):
    row=''
    for j in range(len(grid[i])):
        if (i,j) in visited:
            row+='o'
        else:
            row+=grid[i][j]
    print(row)
