with open('maze.txt') as f:
    grid = [list(line) for line in f.read().splitlines()]
R = len(grid); C = len(grid[0])
start = end = None
for r in range(R):
    for c in range(C):
        if grid[r][c] == '@': start = (r,c)
        if grid[r][c] == 'E': end = (r,c)
from collections import deque
q = deque([start])
prev = {start: None}
while q:
    r,c = q.popleft()
    if (r,c) == end: break
    for dr,dc,d in [(-1,0,'up'),(1,0,'down'),(0,-1,'left'),(0,1,'right')]:
        nr,nc = r+dr, c+dc
        if 0<=nr<R and 0<=nc<C and grid[nr][nc] in '.E' and (nr,nc) not in prev:
            prev[(nr,nc)] = ((r,c), d)
            q.append((nr,nc))
print("end in prev:", end in prev)
path = []
cur = end
while prev.get(cur) is not None:
    pc, d = prev[cur]
    path.append(d)
    cur = pc
path.reverse()
print(' '.join(path))
print(len(path), "moves")
EOF"}

