from collections import deque

with open('maze.txt') as f:
    maze = [list(line) for line in f.read().splitlines()]

rows = len(maze)
cols = max(len(r) for r in maze)
# pad
for r in maze:
    while len(r) < cols:
        r.append(' ')

start = None
end = None
for i in range(rows):
    for j in range(cols):
        if maze[i][j] == '@':
            start = (i,j)
        elif maze[i][j] == 'E':
            end = (i,j)

print("start", start, "end", end)

# BFS
q = deque([start])
visited = {start: None}
dirs = {'up':(-1,0),'down':(1,0),'left':(0,-1),'right':(0,1)}
while q:
    cur = q.popleft()
    if cur == end:
        break
    for d,(di,dj) in dirs.items():
        ni,nj = cur[0]+di, cur[1]+dj
        if 0<=ni<rows and 0<=nj<cols and maze[ni][nj] in '.E' and (ni,nj) not in visited:
            visited[(ni,nj)] = (cur, d)
            q.append((ni,nj))

# reconstruct
path = []
cur = end
while visited[cur] is not None:
    prev, d = visited[cur]
    path.append(d)
    cur = prev
path.reverse()
print(len(path))
print(' '.join(path))
EOF"}

