    for j in range(C):
        if maze[i][j] == '@': start = (i,j)
        if maze[i][j] == 'E': end = (i,j)

def bfs():
    q = deque([start])
    prev = {start: None}
    while q:
        r,c = q.popleft()
        if (r,c) == end:
