grid = lines
# print rows 14-28, cols 18-21 with S/E markers
from collections import deque
R=len(grid); C=len(grid[0])
start=(1,1); end=(29,29)
q=deque([start]); vs={start}
dirs=[(-1,0),(1,0),(0,-1),(0,1)]
while q:
    r,c=q.popleft()
    for dr,dc in dirs:
        nr,nc=r+dr,c+dc
        if 0<=nr<R and 0<=nc<C and grid[nr][nc] in '.E@' and (nr,nc) not in vs:
            vs.add((nr,nc)); q.append((nr,nc))
q2=deque([end]); ve={end}
while q2:
    r,c=q2.popleft()
    for dr,dc in dirs:
        nr,nc=r+dr,c+dc
        if 0<=nr<R and 0<=nc<C and grid[nr][nc] in '.E@' and (nr,nc) not in ve:
            ve.add((nr,nc)); q2.append((nr,nc))
print('     ', ' '.join(f'{j:2}' for j in range(18,22)))
for i in range(14,29):
    row=[]
    for j in range(18,22):
        if (i,j) in vs: row.append('S')
        elif (i,j) in ve: row.append('E')
        else: row.append(grid[i][j])
    print(f'R{i:2}:', ' '.join(f' {x}' for x in row))
print()
print('Col 19:')
for i in range(14,29):
    print(f'  R{i}: {repr(grid[i][19])}')
print()
print('Col 20:')
for i in range(14,29):
    print(f'  R{i}: {repr(grid[i][20])}')
print()
print('Col 21:')
for i in range(14,29):
    print(f'  R{i}: {repr(grid[i][21])}')
""}

